{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "status",
      "type": "'info' | 'warning' | 'error' | 'success'",
      "description": "Status type controlling icon and color.",
      "required": true
    },
    {
      "name": "title",
      "type": "ReactNode",
      "description": "Title text or ReactNode displayed in the header.",
      "required": true
    },
    {
      "name": "description",
      "type": "ReactNode",
      "description": "Description text rendered below the title in the header."
    },
    {
      "name": "icon",
      "type": "ReactNode",
      "description": "Override the default status icon.",
      "slotElements": [
        {
          "__element": "Icon",
          "props": {
            "icon": "check",
            "size": "sm"
          }
        }
      ]
    },
    {
      "name": "isDismissable",
      "type": "boolean",
      "description": "Whether the banner can be dismissed by the user.",
      "default": "false"
    },
    {
      "name": "onDismiss",
      "type": "() => void",
      "description": "Called when the dismiss button is clicked; banner hides itself regardless of whether this is provided."
    },
    {
      "name": "dismissLabel",
      "type": "string",
      "description": "Accessible name and visible tooltip for the dismiss button (pass it already translated). Defaults to \"Dismiss <title>\" for a string title, so stacked banners are distinguishable; set it when the title is a ReactNode."
    },
    {
      "name": "endContent",
      "type": "ReactNode",
      "description": "Action content rendered in the header area, end-aligned. Wraps to its own row below the text when the header is too narrow to hold both.",
      "slotElements": [
        {
          "__element": "Icon",
          "props": {
            "icon": "chevronDown",
            "size": "sm"
          }
        },
        {
          "__element": "Badge",
          "props": {
            "label": "3"
          }
        }
      ]
    },
    {
      "name": "container",
      "type": "'card' | 'section'",
      "description": "Container type: card has border-radius; section is full-width with no border-radius for page-level use.",
      "default": "'card'"
    },
    {
      "name": "elevation",
      "type": "'none' | 'low' | 'med' | 'high'",
      "description": "Resting shadow depth. Use for a floating banner that hovers above content; `none` is the default inline banner. A `card`-container banner rounds its shadow to match.",
      "default": "'none'"
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Content rendered in the card-background area below the colored header. Sits behind an expand/collapse toggle unless `collapsible={false}`."
    },
    {
      "name": "collapsible",
      "type": "boolean | {defaultIsOpen?: boolean; isOpen?: boolean; onOpenChange?: (isOpen: boolean) => void}",
      "description": "Whether the content area (children) sits behind an expand/collapse toggle in the header. On by default, starting collapsed. `false` opts out: children are always visible with no toggle. `{defaultIsOpen: true}` starts open; `{isOpen, onOpenChange}` is controlled. Takes the same CollapsibleConfig as Collapsible.",
      "default": "true"
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
